-- Reference data of the catalog: colors, categories, materials.
--
-- Plain tables, not event-sourced: they change rarely, carry no business rules, and nobody needs their history.
-- Column names are camelCase like the Exposed table objects, so every one with a capital letter is quoted.
-- The CHECKs repeat the rules of the value objects; they are the last line of defence against bad data
-- written by hand or by a future bug.

CREATE TABLE color_tbl
(
    "pId"       BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "colorKey"  VARCHAR(31) NOT NULL UNIQUE CHECK ("colorKey" ~ '^[a-z][a-z0-9-]{1,30}$'),
    name        VARCHAR(50) NOT NULL CHECK (btrim(name) <> ''),
    hex         VARCHAR(7)  NOT NULL CHECK (hex ~ '^#[0-9A-Fa-f]{6}$'),
    "isLight"   BOOLEAN     NOT NULL DEFAULT FALSE,
    "sortOrder" INTEGER     NOT NULL DEFAULT 0
);

CREATE TABLE category_tbl
(
    "pId"          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    -- At least one letter, so GET /products/{idOrSlug} can tell a slug from a numeric id.
    slug           VARCHAR(100) NOT NULL UNIQUE CHECK (slug ~ '^(?=.*[a-z])[a-z0-9]+(-[a-z0-9]+)*$'),
    name           VARCHAR(100) NOT NULL CHECK (btrim(name) <> ''),
    description    TEXT,
    "iconBagType"  VARCHAR(20)  NOT NULL CHECK ("iconBagType" IN
                                                ('HOBO', 'CROSSBODY', 'BACKPACK', 'SATCHEL', 'CLUTCH', 'TOTE', 'BUCKET', 'WALLET')),
    "iconColorKey" VARCHAR(31)  NOT NULL REFERENCES color_tbl ("colorKey"),
    "sortOrder"    INTEGER      NOT NULL DEFAULT 0,
    "showInMenu"   BOOLEAN      NOT NULL DEFAULT TRUE
);

CREATE TABLE material_tbl
(
    "pId"              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    slug               VARCHAR(100) NOT NULL UNIQUE CHECK (slug ~ '^(?=.*[a-z])[a-z0-9]+(-[a-z0-9]+)*$'),
    name               VARCHAR(120) NOT NULL CHECK (btrim(name) <> ''),
    family             VARCHAR(20)  NOT NULL CHECK (family IN
                                                    ('GENUINE_LEATHER', 'FAUX_LEATHER', 'CANVAS', 'SUEDE', 'FAUX_SUEDE',
                                                     'SATIN', 'VELVET', 'COTTON', 'OTHER')),
    description        TEXT,
    "careInstructions" TEXT[]       NOT NULL DEFAULT '{}'
);
